export class StudioAudio{
 constructor(){this.enabled=false;this.ctx=null;this.sources=[];this.key='';}
 async enable(value){this.enabled=value;if(!value){this.stop();return;}try{this.ctx??=new(window.AudioContext||window.webkitAudioContext)();await this.ctx.resume();}catch{this.enabled=false;}}
 stop(){for(const s of this.sources)try{s.stop();}catch{}this.sources=[];this.key='';}
 update(sim){const key=sim.grinding?'grind':sim.brewing?'brew':Math.abs(sim.stirVelocity)>.1?'stir':sim.flow?'pour':'';if(!this.enabled||document.hidden){this.stop();return;}if(key===this.key)return;this.stop();this.key=key;if(!key||!this.ctx)return;const ctx=this.ctx,gain=ctx.createGain();gain.gain.value=key==='stir'?.04:.025;gain.connect(ctx.destination);const data=ctx.createBuffer(1,ctx.sampleRate*2,ctx.sampleRate);for(let d=data.getChannelData(0),i=0;i<d.length;i++)d[i]=Math.random()*2-1;const source=ctx.createBufferSource();source.buffer=data;source.loop=true;const filter=ctx.createBiquadFilter();filter.type='lowpass';filter.frequency.value=key==='stir'?1500:key==='grind'?1100:500;source.connect(filter);filter.connect(gain);source.start();this.sources.push(source);if(key!=='pour'){const osc=ctx.createOscillator();osc.type='triangle';osc.frequency.value=key==='stir'?90:key==='grind'?140:65;osc.connect(gain);osc.start();this.sources.push(osc);}}
 clink(){if(!this.enabled||!this.ctx)return;const ctx=this.ctx,o=ctx.createOscillator(),g=ctx.createGain();o.frequency.value=1400+Math.random()*400;g.gain.setValueAtTime(.035,ctx.currentTime);g.gain.exponentialRampToValueAtTime(.0001,ctx.currentTime+.18);o.connect(g);g.connect(ctx.destination);o.start();o.stop(ctx.currentTime+.2);}
}
